package com.wardk.meeteam_backend.domain.github.activity;
import com.fasterxml.jackson.databind.*;
import com.wardk.meeteam_backend.domain.github.integration.*;
import com.wardk.meeteam_backend.domain.github.account.MemberGithubAccount;
import com.wardk.meeteam_backend.domain.member.entity.Member;
import com.wardk.meeteam_backend.web.github.activity.GithubActivityResponses.*;
import com.wardk.meeteam_backend.global.exception.CustomException;
import com.wardk.meeteam_backend.global.response.ErrorCode;
import jakarta.persistence.*;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static com.wardk.meeteam_backend.domain.github.activity.GithubActivityRules.*;
@Service @Transactional(readOnly=true)
public class GithubActivityQuery {
 private final EntityManager em;private final GithubProjectAccess access;private final ObjectMapper json;private final Clock clock;
 public GithubActivityQuery(EntityManager em,GithubProjectAccess access,ObjectMapper json,@Qualifier("githubActivityClock") Clock clock){this.em=em;this.access=access;this.json=json;this.clock=clock;}
 public Map<Long,GithubActivitySummary> summaries(Collection<Long> projectIds){if(projectIds.isEmpty())return Map.of();var rows=em.createQuery("select l.projectId,s.lastPushedAt from GithubProjectLink l left join GithubRepositorySnapshot s on s.repositoryId=l.githubRepositoryId where l.projectId in :ids and l.installationActive=true and l.githubRepositoryId is not null and s.syncedAt is not null",Object[].class).setParameter("ids",projectIds).getResultList();var result=new HashMap<Long,GithubActivitySummary>();for(var r:rows)result.put((Long)r[0],new GithubActivitySummary(level((Instant)r[1],clock.instant()),(Instant)r[1]));return result;}
 private GithubProjectLink link(long project){var l=em.find(GithubProjectLink.class,project);return l!=null&&l.hasRepository()?l:null;}
 private GithubRepositorySnapshot snapshot(long repositoryId){var s=em.find(GithubRepositorySnapshot.class,repositoryId);if(s==null||s.getSyncedAt()==null)throw new CustomException(ErrorCode.GITHUB_UPSTREAM_ERROR,"GitHub 개발 현황을 동기화하고 있습니다. 잠시 후 다시 시도해 주세요.");return s;}
 private GithubProjectLink required(long project){var l=link(project);if(l==null)throw new CustomException(ErrorCode.GITHUB_REPOSITORY_NOT_LINKED);return l;}
 public Activity activity(long project,Long member){access.requirePublic(project);var l=link(project);if(l==null)return null;var s=snapshot(l.getGithubRepositoryId());boolean redact=l.isRepositoryPrivate()&&!access.isTeam(project,member);var contributors=new ArrayList<Contributor>();if(!redact){var nodes=parse(s.getContributors());var ids=new ArrayList<Long>();for(var n:nodes)if(n.path("id").isNumber())ids.add(n.path("id").asLong());Map<Long,MemberGithubAccount> accounts=new HashMap<>();if(!ids.isEmpty())for(var a:em.createQuery("select a from MemberGithubAccount a join fetch a.member where a.githubUserId in :ids",MemberGithubAccount.class).setParameter("ids",ids).getResultList())accounts.put(a.getGithubUserId(),a);for(var n:nodes){var a=accounts.get(n.path("id").asLong());contributors.add(new Contributor(n.path("login").asText(""),n.path("avatar_url").asText(""),n.path("contributions").asInt(),a==null?null:a.getMemberId(),a==null?null:a.getMember().getRealName()));}}
  var languages=new ArrayList<Language>();for(var n:parse(s.getLanguages()))languages.add(new Language(n.path("name").asText(),n.path("percentage").asDouble()));
  // Private repository identity is deliberately blank for non-team viewers; only aggregates are public.
  var repo=new Repository(redact?0:l.getGithubRepositoryId(),redact?"":text(l.getFullName()),redact?"":text(l.getHtmlUrl()),redact?"":text(l.getDescription()),l.isRepositoryPrivate(),redact?"":text(l.getDefaultBranch()),l.getStars(),l.getForks());
  var times=em.createQuery("select e.occurredAt from GithubActivityEvent e where e.repositoryId=:repo and e.type='COMMIT' and e.occurredAt>=:start",Instant.class).setParameter("repo",l.getGithubRepositoryId()).setParameter("start",start(monday(clock.instant()).minusWeeks(7))).getResultList();
  return new Activity(repo,level(s.getLastPushedAt(),clock.instant()),s.getLastPushedAt(),weeks(times,clock.instant()),s.getOpenPullRequestCount(),s.getOpenIssueCount(),languages,contributors,s.getSyncedAt());
 }
 public Progress progress(long project,Long member){access.requireTeam(project,member);var l=required(project);snapshot(l.getGithubRepositoryId());Instant now=clock.instant(),from=now.minus(Duration.ofDays(28));var team=team(project);var prs=em.createQuery("select p from GithubPullRequest p where p.repositoryId=:repo and p.open=true order by p.number",GithubPullRequest.class).setParameter("repo",l.getGithubRepositoryId()).getResultList();var byGithub=byGithub(team);var result=prs.stream().map(p->{var a=byGithub.get(p.getGithubUserId());return new PullRequest(p.getNumber(),p.getTitle(),p.getUrl(),p.getAuthorLogin(),a==null?null:a.name,p.isDraft(),p.getReviewDecision()==null?"REVIEW_REQUIRED":p.getReviewDecision(),p.getCreatedAt(),p.getUpdatedAt(),stale(p.isDraft(),p.getReviewDecision(),p.getUpdatedAt(),now));}).toList();return new Progress(from.atZone(SEOUL).toLocalDate(),now.atZone(SEOUL).toLocalDate(),result,contributions(team,events(l.getGithubRepositoryId(),from,now.plusNanos(1))));}
 public WeeklyReport weekly(long project,Long member,LocalDate week){access.requireTeam(project,member);var l=required(project);if(week.getDayOfWeek()!=DayOfWeek.MONDAY)throw new CustomException(ErrorCode.GITHUB_INVALID_REQUEST,"시작일은 월요일이어야 합니다.");if(week.isAfter(monday(clock.instant())))throw new CustomException(ErrorCode.GITHUB_INVALID_REQUEST,"아직 시작하지 않은 주입니다.");snapshot(l.getGithubRepositoryId());var team=team(project);var by=byGithub(team);var events=events(l.getGithubRepositoryId(),start(week),start(week.plusWeeks(1)));var authorLogins=new HashMap<Integer,String>();for(var p:em.createQuery("select p from GithubPullRequest p where p.repositoryId=:repo",GithubPullRequest.class).setParameter("repo",l.getGithubRepositoryId()).getResultList())authorLogins.put(p.getNumber(),p.getAuthorLogin());var merged=new ArrayList<Merged>();var closed=new ArrayList<Closed>();long commits=0,opened=0;for(var e:events){switch(e.getType()){case "COMMIT"->commits++;case "ISSUE_OPENED"->opened++;case "PR_MERGED"->{var a=by.get(e.getGithubUserId());merged.add(new Merged(e.getNumber(),e.getTitle(),e.getUrl(),a==null?text(authorLogins.get(e.getNumber())):text(a.login),a==null?null:a.name,e.getOccurredAt()));}case "ISSUE_CLOSED"->closed.add(new Closed(e.getNumber(),e.getTitle(),e.getUrl(),e.getOccurredAt()));default->{}}}return new WeeklyReport(week,week.plusDays(6),new Summary(commits,merged.size(),opened,closed.size()),merged,closed,contributions(team,events));}
 private List<GithubActivityEvent> events(long repo,Instant from,Instant until){return em.createQuery("select e from GithubActivityEvent e where e.repositoryId=:repo and e.occurredAt>=:from and e.occurredAt<:until order by e.occurredAt,e.id",GithubActivityEvent.class).setParameter("repo",repo).setParameter("from",from).setParameter("until",until).getResultList();}
 private record Team(long id,String name,Long githubId,String login){}
 private List<Team> team(long project){var members=em.createQuery("select distinct m from Member m where m.id in (select pm.member.id from ProjectMember pm where pm.project.id=:project) or m.id in (select p.creator.id from Project p where p.id=:project)",Member.class).setParameter("project",project).getResultList();if(members.isEmpty())return List.of();var ids=members.stream().map(Member::getId).toList();var accounts=em.createQuery("select a from MemberGithubAccount a where a.memberId in :ids",MemberGithubAccount.class).setParameter("ids",ids).getResultList();var by=new HashMap<Long,MemberGithubAccount>();for(var a:accounts)by.put(a.getMemberId(),a);return members.stream().map(m->{var a=by.get(m.getId());return new Team(m.getId(),m.getRealName(),a==null?null:a.getGithubUserId(),a==null?null:a.getLogin());}).sorted(Comparator.comparingLong(Team::id)).toList();}
 private Map<Long,Team> byGithub(List<Team> team){var map=new HashMap<Long,Team>();for(var t:team)if(t.githubId!=null)map.put(t.githubId,t);return map;}
 private List<Contribution> contributions(List<Team> team,List<GithubActivityEvent> events){var counts=new HashMap<Long,long[]>();for(var e:events){if(e.getGithubUserId()==null)continue;var n=counts.computeIfAbsent(e.getGithubUserId(),k->new long[3]);switch(e.getType()){case "COMMIT"->n[0]++;case "PR_MERGED"->n[1]++;case "REVIEW"->n[2]++;default->{}}}return team.stream().map(t->{var n=counts.getOrDefault(t.githubId,new long[3]);return new Contribution(t.id,t.name,t.login,n[0],n[1],n[2]);}).toList();}
 private JsonNode parse(String value){try{return json.readTree(value);}catch(Exception ex){throw new IllegalStateException("Invalid stored GitHub metadata");}}
 private static String text(String s){return s==null?"":s;}
}
